// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

/**
* Interface describing `dlabad`.
*/
interface Routine {
	/**
	* Adjust the underflow and overflow thresholds if the exponent range is very large (no-op on IEEE-754 machines).
	*
	* @param SMALL - array containing a single element equal to the underflow threshold
	* @param LARGE - array containing a single element equal to the overflow threshold
	* @returns void
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var SMALL = new Float64Array( [ 2.2250738585072014e-308 ] );
	* var LARGE = new Float64Array( [ 1.7976931348623157e+308 ] );
	*
	* dlabad( SMALL, LARGE );
	* // SMALL => <Float64Array>[ 2.2250738585072014e-308 ]
	* // LARGE => <Float64Array>[ 1.7976931348623157e+308 ]
	*/
	( SMALL: Float64Array, LARGE: Float64Array ): void;

	/**
	* Adjust the underflow and overflow thresholds if the exponent range is very large (no-op on IEEE-754 machines) using alternative indexing semantics.
	*
	* @param SMALL - array containing an element equal to the underflow threshold
	* @param offsetSMALL - index of the element in `SMALL`
	* @param LARGE - array containing an element equal to the overflow threshold
	* @param offsetLARGE - index of the element in `LARGE`
	* @returns void
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var SMALL = new Float64Array( [ 2.2250738585072014e-308 ] );
	* var LARGE = new Float64Array( [ 1.7976931348623157e+308 ] );
	*
	* dlabad.ndarray( SMALL, 0, LARGE, 0 );
	* // SMALL => <Float64Array>[ 2.2250738585072014e-308 ]
	* // LARGE => <Float64Array>[ 1.7976931348623157e+308 ]
	*/
	ndarray( SMALL: Float64Array, offsetSMALL: number, LARGE: Float64Array, offsetLARGE: number ): void;
}

/**
* Adjust the underflow and overflow thresholds if the exponent range is very large (no-op on IEEE-754 machines).
*
* @param SMALL - array containing a single element equal to the underflow threshold
* @param LARGE - array containing a single element equal to the overflow threshold
* @returns void
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var SMALL = new Float64Array( [ 2.2250738585072014e-308 ] );
* var LARGE = new Float64Array( [ 1.7976931348623157e+308 ] );
*
* dlabad( SMALL, LARGE );
* // SMALL => <Float64Array>[ 2.2250738585072014e-308 ]
* // LARGE => <Float64Array>[ 1.7976931348623157e+308 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var SMALL = new Float64Array( [ 2.2250738585072014e-308 ] );
* var LARGE = new Float64Array( [ 1.7976931348623157e+308 ] );
*
* dlabad.ndarray( SMALL, 0, LARGE, 0 );
* // SMALL => <Float64Array>[ 2.2250738585072014e-308 ]
* // LARGE => <Float64Array>[ 1.7976931348623157e+308 ]
*/
declare var dlabad: Routine;


// EXPORTS //

export = dlabad;
